import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen1Test {

    private Cleaner cleaner;
    private Whitelist whitelist;

    @Before
    public void setUp() {
        // Using basic whitelist for testing
        whitelist = Whitelist.basic();
        cleaner = new Cleaner(whitelist);
    }

    @Test
    public void isValid_withSafeDocument_returnsTrue() {
        Document dirtyDocument = Jsoup.parse("<p>Hello World</p>");
        // This document is fully compliant with basic whitelist
        boolean result = cleaner.isValid(dirtyDocument);
        assertTrue("Document with only safe tags should be valid", result);
    }










}

