import org.jsoup.parser.Tag;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen1Test {

    private Cleaner cleaner;
    private Whitelist whitelist;

    @Before
    public void setUp() {
        // Using basic whitelist for testing
        whitelist = Whitelist.basic();
        cleaner = new Cleaner(whitelist);
    }







    @Test
    public void isValid_withUnsafeAttributes_returnsFalse() {
        Document dirtyDocument = Jsoup.parse("<p style='color:red;'>Text</p>");
        // Basic whitelist might allow some attributes, but if we use a strict one:
        Cleaner strictCleaner = new Cleaner(Whitelist.none());
        boolean result = strictCleaner.isValid(dirtyDocument);
        assertFalse("Document with unauthorized attributes should be invalid", result);
    }




}

