public class Cleaner_isValid_TriageGen1Test {

    private Cleaner cleaner;
    private Whitelist whitelist;

    @Before
    public void setUp() {
        // Using basic whitelist for testing
        whitelist = Whitelist.basic();
        cleaner = new Cleaner(whitelist);
    }











    @Test
    public void isValid_withMixedContent_returnsFalse() {
        Document dirtyDocument = Jsoup.parse("<div><p>Safe</p><iframe src='bad'></iframe></div>");
        // iframe is not in basic whitelist
        boolean result = cleaner.isValid(dirtyDocument);
        assertFalse("Document with mixed safe and unsafe nodes should be invalid", result);
    }
}
